import{d as p,C as t,o as m,c as g,j as a,a as o,E as n,k as b,a3 as x}from"./chunks/framework.Q4yG9rk_.js";const k=JSON.parse('{"title":"道德经第一章","description":"从道与名、始与母、妙与徼进入第一章，附逐段白话、王弼注择要与校读说明。","frontmatter":{"title":"道德经第一章","description":"从道与名、始与母、妙与徼进入第一章，附逐段白话、王弼注择要与校读说明。","category":"guide","aliases":["道德经第一章","老子第一章","道可道","dao de jing chapter 1"],"source":["王弼《道德真经注》卷一"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-01.md","filePath":"daoism/dao-de-jing/chapter-01.md","lastUpdated":1794189804000}'),y={name:"daoism/dao-de-jing/chapter-01.md"},q=p({...y,setup(f){const i=[{id:"opening",label:"道可道，非常道",showLabel:!0,sentences:[[{text:"道",glossary:"dao-noun"},"可",{text:"道",glossary:"dao-verb"},"，非",{text:"常",glossary:"chang"},"道。"],[{text:"名",glossary:"ming-noun"},"可",{text:"名",glossary:"ming-verb"},"，非常名。"]],note:["【白话】可以用言语指陈、限定为某种具体事物的道，不是恒常的道；可以确定为某个名称的名，也不是恒常的名。","【王弼注择要】「可道之道，可名之名，指事造形，非其常也。」这里先区分具体的言说、名称与它们无法穷尽的根本。","【读法】第一个「道」是所谈的道，第二个「道」是言说；第一个「名」是名称，第二个「名」是命名。开篇仍在用语言引路，重点在于警惕把某个说法当成最终限定。"]},{id:"beginning-and-mother",label:"无名，天地之始",showLabel:!0,sentences:[[{text:"无名",glossary:"wuming"},"，天地之始；"],[{text:"有名",glossary:"youming"},"，万物之母。"]],note:["【白话】无形无名之时，是天地的开端；有形有名之时，则成为生养万物的母体。","【王弼注择要】「凡有皆始于无」，又以「未形无名之时」说明「始」，以「有形有名之时」说明「母」。这一路解释将开端与生养联系起来。","【读法】本页将「无名」「有名」连读。「始」着眼于发端，「母」着眼于生养；理解这一对，才能接上篇末「此两者」的王弼注。"]},{id:"observation",label:"故常无欲，以观其妙",showLabel:!0,sentences:[["故常",{text:"无欲",glossary:"wuyu"},"，以观其",{text:"妙",glossary:"miao"},"；"],["常",{text:"有欲",glossary:"youyu"},"，以观其",{text:"徼",glossary:"jiao"},"。"]],note:["【白话】因此，常在无所贪求、虚静的状态下，观察万物发端时的幽微；在有所欲求时，则观察事物显现、发展所至的归结。","【王弼注择要】「妙者，微之极也。」「徼，归终也。」王弼分别从「始物」与「终物」解释所观的层次，提示我们同时留意发端与归结。","【读法】「有欲」仍有欲求之意，不能直接改译成理性或客观观察。这两句也不能推出欲望越多越好；本页的现代启发只作阅读联想，不冒充原文逐字本义。"]},{id:"return",label:"此两者，同出而异名",showLabel:!0,sentences:[["此两者，同出而异名，同谓之",{text:"玄",glossary:"xuan"},"。"],[{text:"玄",glossary:"xuan"},"之又玄，众妙之门。"]],note:["【白话】这两者出于同一根源，却有不同的名称，都可称为幽深的玄。玄而又玄，是种种幽微之理所由出的门径。","【王弼注择要】「两者，始与母也。」「在首则谓之始，在终则谓之母。」本页依此将「两者」落实为前文的「始」与「母」，不把其他解释直接归给王弼。","【读法】王弼又提醒「不可以定乎一玄而已」：连「玄」也不能成为一个固定的终点名称。全章从道与名起笔，最终回到名称能否穷尽根源的问题。"]}],r=[{id:"dao-noun",term:"道",sense:1,context:"「道可道」的第一个「道」，是所谈的根本之道。"},{id:"dao-verb",term:"道",sense:2,context:"「道可道」的第二个「道」，作言说、称述解。"},{id:"ming-noun",term:"名",sense:2,context:"「名可名」的第一个「名」，作名称、名号解。"},{id:"ming-verb",term:"名",sense:1,context:"「名可名」的第二个「名」，作命名解。"},{id:"chang",term:"常",sense:1},{id:"wuming",term:"无名",sense:1},{id:"youming",term:"有名",sense:1},{id:"wuyu",term:"无欲",sense:1},{id:"youyu",term:"有欲",sense:1},{id:"miao",term:"妙",sense:1},{id:"jiao",term:"徼",sense:1},{id:"xuan",term:"玄",sense:1,context:"王弼以「冥」释玄，并提醒不可把「玄」限定成一个固定名称。"}],l=r.filter(s=>!["dao-verb","ming-verb"].includes(s.id));return(s,e)=>{const d=t("DaoReadingPrelude"),u=t("DaoTextReading"),c=t("DaoLineGuide"),h=t("DaoKeywordCards");return m(),g("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第一章",tabindex:"-1"},[o("道德经第一章 "),a("a",{class:"header-anchor",href:"#道德经第一章","aria-label":'Permalink to "道德经第一章"'},"​")],-1)),n(d,{title:"先读道与名，再辨始与母",summary:"第一章从道与名的限度说起，经由无名与有名、妙与徼，最后收回到「玄」。本页循王弼注的取径，分四个语义段，先读原文，再就地看白话与注释。",points:[{label:"先读",text:"通读四段，留意「道」「名」各有两种用法。"},{label:"再辨",text:"看「始／母」「妙／徼」怎样承接发端与生成。"},{label:"后想",text:"为什么说到「玄」，仍要再说「玄之又玄」？"}],hint:"竹简模式先通读；切到经典阅读后，点段首原文标签展开释义，或用「释义」开关全部展开。带标记的字词可点击查义。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段级释义",tabindex:"-1"},[o("【原典层】原文与段级释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段级释义","aria-label":'Permalink to "【原典层】原文与段级释义"'},"​")],-1)),e[2]||(e[2]=a("blockquote",null,[a("p",null,"正文依据王弼《道德真经注》卷一核对，采用简体字与现代标点；白话及引读为本站整理，王弼注引文另作标识。具体底本与断句取法见篇末。")],-1)),n(u,{sections:i,glossary:r,tone:"ink",density:"comfortable","aria-label":"《道德经》第一章原文"}),e[3]||(e[3]=a("h2",{id:"【导读层】核心句引读",tabindex:"-1"},[o("【导读层】核心句引读 "),a("a",{class:"header-anchor",href:"#【导读层】核心句引读","aria-label":'Permalink to "【导读层】核心句引读"'},"​")],-1)),n(c,{lines:[{text:"道可道，非常道；名可名，非常名。",tone:"开门",guide:"先辨词性，再辨限度：言说和名称可以指认事物，但某个具体说法不能穷尽恒常之道。"},{text:"无名，天地之始；有名，万物之母。",tone:"展开",guide:"依王弼注，由未形无名说「始」，由有形有名说「母」。一边追溯发端，一边说明生养，这是同一生成过程的不同着眼点。"},{text:"故常无欲，以观其妙；常有欲，以观其徼。",tone:"观法",guide:"「妙」与「徼」承接发端与归结。先看词义，再理解观察所至；不要直接把无欲、有欲替换成感性、理性或主观、客观。"},{text:"此两者，同出而异名。",tone:"回收",guide:"王弼明确注为「两者，始与母也」。回指前文时，要区分这一路注法与把「两者」理解为无与有、无欲与有欲的其他读法。"},{text:"玄之又玄，众妙之门。",tone:"收束",guide:"连「玄」也不能被当成已经握住根源的固定答案。收尾继续打开追问的入口，与开篇对道、名的提醒相呼应。"}]}),e[4]||(e[4]=a("h2",{id:"【注释层】字词释义",tabindex:"-1"},[o("【注释层】字词释义 "),a("a",{class:"header-anchor",href:"#【注释层】字词释义","aria-label":'Permalink to "【注释层】字词释义"'},"​")],-1)),n(h,{items:b(l)},null,8,["items"]),e[5]||(e[5]=x('<p>同一个字在句中可以承担不同作用。「道」「名」的名词、动词义已在原文分别标注；词卡列出本章主要字词，完整义项可从字典查看。</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-为什么从「道与名」走到「始与母」" tabindex="-1">象：为什么从「道与名」走到「始与母」？ <a class="header-anchor" href="#象-为什么从「道与名」走到「始与母」" aria-label="Permalink to &quot;象：为什么从「道与名」走到「始与母」？&quot;">​</a></h3><p>开篇先问：我们说出来的道、确定下来的名，能否等同于恒常之道与名？接着，文字把视野移向天地万物的发端与生成，再由「妙」「徼」说到观察所能抵达的层次。</p><p>循王弼注读下去，「始」与「母」是贯穿中间两段和末段的线索：未形无名时称「始」，有形有名而生养万物时称「母」。名称随所指的层次而不同，但所追溯的根源相通。</p><h3 id="理-既然名有限-为什么还要说「玄」" tabindex="-1">理：既然名有限，为什么还要说「玄」？ <a class="header-anchor" href="#理-既然名有限-为什么还要说「玄」" aria-label="Permalink to &quot;理：既然名有限，为什么还要说「玄」？&quot;">​</a></h3><p>完全不用语言，读者便无从进入；把语言当成已经把握根源，又会停在一个具体说法上。第一章让这份张力留在文字里：先说道、名，再说始、母，最后以「玄」暂作指称。</p><p>王弼说「不可以定乎一玄而已」，正是在防止读者把「玄」重新做成一个封闭答案。「玄之又玄」使追问继续开放，也回应了开篇对名称限度的提醒。</p><h3 id="用-怎样读-才不会把「无欲-有欲」读成两句口号" tabindex="-1">用：怎样读，才不会把「无欲／有欲」读成两句口号？ <a class="header-anchor" href="#用-怎样读-才不会把「无欲-有欲」读成两句口号" aria-label="Permalink to &quot;用：怎样读，才不会把「无欲／有欲」读成两句口号？&quot;">​</a></h3><p>先核对字词与注法，再谈启发。「无欲」有虚静、减少贪求的一面；「有欲」也仍是欲求，不能为了便于应用就改说成理性分析。王弼对「妙」「徼」的注，提醒读者留意发端与归结。</p><p>读本章时，可以先不急着索取一个结论，逐段看它怎样从言说走向生成，再回到名称的限度。遇到熟悉的词，仍要追问：这里是哪一个义项？这一理解来自原文、古注，还是自己的联想？</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p>以下是从本章引出的现代阅读联想，供继续思考。</p><p><strong>给概念留出修订的空间。</strong> 学习时，定义和分类帮助人建立秩序。读过一段时间后，也要回到具体文本与事实，检查原来的名称是否仍然合适，是否遗漏了新的层次。</p><p><strong>让目标给观察留一点余地。</strong> 带着问题读书有助于集中注意，但若每一句都急着拿来证明预设，就容易只看见自己想要的答案。可以先通读，再细辨，最后整理结论；这是阅读方法上的借鉴，不是把「无欲／有欲」直接翻译成两种现代思维工具。</p><p><strong>同时追问从哪里来、怎样形成。</strong> 「始」与「母」提示了一种可继续使用的提问方式：一件事的发端是什么，又靠什么持续生长？这能帮助我们把注意力从一个静止的标签，移到形成与发展的过程。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><blockquote><p>以下保留本页原有的个人阅读记录，与上文按王弼注整理的取径并列。两者存在的理解差别，留待续读时比较、修订。</p></blockquote><p>这一章让我最先感到的，不是抽象概念，而是一种强烈的源头感。</p><p>“无名天地之始”中的“天地之始”，让人自然感到宏大、广博，也让人意识到：这里谈的不是某个局部知识点，而是在追问万物未分之前的根。</p><p>我目前更愿意把这一章理解成：</p><ul><li><code>无名</code> 不是空无，而是未分、未定、未被概念切开的本始状态</li><li><code>有名</code> 不是错误，而是万物展开之后进入可分、可识、可说的层次</li><li><code>无欲</code> 与 <code>有欲</code> 不是价值上的绝对好坏，而是两种观看世界的方式</li></ul><p>所以真正重要的，不是站在哪一边，而是知道自己此刻是在看“源”，还是在看“流”；是在看“深处”，还是在看“轮廓”。</p><p>第一章像是在提醒学习者：不要把语言当终点，不要把名字当实相。先承认语言有边界，后面才真正进得去。</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><h3 id="三处需要留意的读法" tabindex="-1">三处需要留意的读法 <a class="header-anchor" href="#三处需要留意的读法" aria-label="Permalink to &quot;三处需要留意的读法&quot;">​</a></h3><ol><li><strong>「无名／有名」的断句</strong>：本页采用「无名，天地之始；有名，万物之母」，依据王弼以「未形无名」「有形有名」解释始与母。另有「无，名天地之始；有，名万物之母」的断法，取义不同，不混入本页白话。</li><li><strong>「无欲／有欲」的连读</strong>：本页将二者分别连读，以「妙」「徼」为所观。另有将「欲」向下连读的方案，本页不据此改动正文；有关当代观察方法的联想也不直接当作这两个词的本义。</li><li><strong>「此两者」的回指</strong>：本页循王弼「两者，始与母也」理解；无与有、无欲与有欲等其他回指方式，可在后续比较阅读中另辨，不能无说明地互相替换。</li></ol><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_001.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷一 HFL 本电子录文，001a–002a</a>。</p>',28))])}}});export{k as __pageData,q as default};
